{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2155-11-03 16:45:00",
      "speaker": "Doctor",
      "text": "Hello, I’m Dr. Lee. I’ll be taking care of you today. I understand you’ve been having abdominal pain, nausea, and diarrhea?"
    },
    {
      "turn_number": 2,
      "time": "2155-11-03 16:46:00",
      "speaker": "Patient",
      "text": "Yes, that’s right. It started a few days ago—sharp pain in the middle of my belly, going to my back. Feels just like my old pancreatitis flares."
    },
    {
      "turn_number": 3,
      "time": "2155-11-03 16:47:00",
      "speaker": "Doctor",
      "text": "I see. And the nausea—any vomiting?"
    },
    {
      "turn_number": 4,
      "time": "2155-11-03 16:47:30",
      "speaker": "Patient",
      "text": "No vomiting, but the nausea is constant. And the diarrhea—it looks oily, like it floats."
    },
    {
      "turn_number": 5,
      "time": "2155-11-03 16:48:15",
      "speaker": "Doctor",
      "text": "That can happen with pancreatitis when the pancreas isn’t making enough enzymes. We’ve checked your blood, and your lipase is mildly elevated at 86, which supports that idea."
    },
    {
      "turn_number": 6,
      "time": "2155-11-03 16:49:00",
      "speaker": "Patient",
      "text": "Is that high? Last time it was over 100."
    },
    {
      "turn_number": 7,
      "time": "2155-11-03 16:50:00",
      "speaker": "Doctor",
      "text": "It’s on the lower end, but still above normal. Given your history, we’re treating this as a mild flare of your chronic pancreatitis."
    },
    {
      "turn_number": 8,
      "time": "2155-11-03 16:51:00",
      "speaker": "Patient",
      "text": "Okay. I’ve been taking my usual pain meds, but they’re not helping much."
    },
    {
      "turn_number": 9,
      "time": "2155-11-03 16:52:00",
      "speaker": "Doctor",
      "text": "We’ll give you IV fluids and start you on IV pain medication to help. You’ll also need to rest your bowel for now—no food at first, then we’ll slowly reintroduce it."
    },
    {
      "turn_number": 10,
      "time": "2155-11-03 16:53:00",
      "speaker": "Patient",
      "text": "That’s fine. I haven’t had much appetite anyway."
    },
    {
      "turn_number": 11,
      "time": "2155-11-03 20:15:00",
      "speaker": "Doctor",
      "text": "Hi again. You’ve been doing well. Your vitals are stable, and your pain seems a bit better. We’re going to try a soft diet—start with clear liquids and see how you tolerate it."
    },
    {
      "turn_number": 12,
      "time": "2155-11-03 20:16:30",
      "speaker": "Patient",
      "text": "That sounds good. Can I have some broth?"
    },
    {
      "turn_number": 13,
      "time": "2155-11-03 20:17:15",
      "speaker": "Doctor",
      "text": "Yes, we’ll start with broth and jello. If you keep that down, we’ll advance your diet tomorrow."
    },
    {
      "turn_number": 14,
      "time": "2155-11-04 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. Your labs this morning look stable. Your lipase is trending down, and liver tests are normal. You made it through the night without nausea or pain worsening."
    },
    {
      "turn_number": 15,
      "time": "2155-11-04 08:01:30",
      "speaker": "Patient",
      "text": "I feel much better. I even had a soft roll this morning with no problem."
    },
    {
      "turn_number": 16,
      "time": "2155-11-04 08:02:30",
      "speaker": "Doctor",
      "text": "That’s great. We’ll keep you on a soft diet for now. Since you’re improving, we’re planning to discharge you today."
    },
    {
      "turn_number": 17,
      "time": "2155-11-04 08:03:30",
      "speaker": "Patient",
      "text": "Okay. Should I take anything for nausea or pain at home?"
    },
    {
      "turn_number": 18,
      "time": "2155-11-04 08:04:30",
      "speaker": "Doctor",
      "text": "Yes, we’re prescribing prochlorperazine for nausea if it comes back, and oxycodone 5 mg for pain, just as needed. But use them sparingly."
    },
    {
      "turn_number": 19,
      "time": "2155-11-04 08:05:30",
      "speaker": "Patient",
      "text": "And my regular meds—should I keep taking those?"
    },
    {
      "turn_number": 20,
      "time": "2155-11-04 08:06:15",
      "speaker": "Doctor",
      "text": "Yes, continue all your home medications—venlafaxine, imipramine, trazodone, prazosin, clonazepam, and ranitidine. They’re important for your mood and GI health."
    },
    {
      "turn_number": 21,
      "time": "2155-11-04 08:07:15",
      "speaker": "Patient",
      "text": "What about the diarrhea? Should I be worried?"
    },
    {
      "turn_number": 22,
      "time": "2155-11-04 08:08:00",
      "speaker": "Doctor",
      "text": "It’s likely due to poor fat digestion from your pancreas. If it continues, your GI doctor might adjust your enzyme supplements. For now, watch your diet—low fat, small meals."
    },
    {
      "turn_number": 23,
      "time": "2155-11-04 08:09:00",
      "speaker": "Patient",
      "text": "Got it. When should I follow up?"
    },
    {
      "turn_number": 24,
      "time": "2155-11-04 08:10:00",
      "speaker": "Doctor",
      "text": "Please see your GI doctor soon. And if you develop fever, worsening pain, vomiting, or can’t keep food down, come back right away."
    },
    {
      "turn_number": 25,
      "time": "2155-11-04 10:30:00",
      "speaker": "Doctor",
      "text": "We’ve reviewed everything, and you’re ready to go home. Your abdomen is soft, you’re walking, and you’ve tolerated food well."
    },
    {
      "turn_number": 26,
      "time": "2155-11-04 10:31:00",
      "speaker": "Patient",
      "text": "Thank you. I’m glad it wasn’t worse."
    },
    {
      "turn_number": 27,
      "time": "2155-11-04 10:32:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Take care, and don’t hesitate to reach out if symptoms return."
    },
    {
      "turn_number": 28,
      "time": "2155-11-04 10:33:00",
      "speaker": "Patient",
      "text": "I will. Thanks again."
    }
  ],
  "summary": {
    "admission_start": "2155-11-03 16:39:00",
    "admission_end": "2155-11-04 15:30:00",
    "summary_paragraph": "A woman with a history of chronic pancreatitis and sphincter of Oddi dysfunction was admitted for acute epigastric abdominal pain, nausea, and fatty diarrhea. Her symptoms were consistent with a mild flare of pancreatitis, supported by a mildly elevated lipase of 86 and normal liver function tests. She was managed conservatively with IV fluids, bowel rest, and symptom control. Pain and nausea improved, and she successfully advanced to a soft diet. She remained hemodynamically stable throughout her stay, with no complications. She was discharged home in stable condition with prescriptions for pain and nausea as needed, and instructions to follow up with her GI provider and monitor for worsening symptoms.",
    "problems": [
      "Abdominal pain, epigastric",
      "Nausea alone",
      "Diarrhea",
      "Chronic pancreatitis",
      "Depressive disorder, not elsewhere classified",
      "Anxiety state, unspecified",
      "Posttraumatic stress disorder",
      "Unspecified hearing loss",
      "Family history of malignant neoplasm of breast"
    ]
  }
}
